"use client";

import React, { useState } from "react";
import { Star, ShieldCheck } from "lucide-react";

export function ReviewListCard() {
  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-1">
          {[1, 2, 3, 4, 5].map((s) => (
            <Star key={s} className="w-3.5 h-3.5 fill-yellow-400 text-yellow-400" />
          ))}
        </div>
        <span className="text-[9px] uppercase font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20 flex items-center gap-0.5">
          <ShieldCheck className="w-3 h-3" /> Verified Buyer
        </span>
      </div>

      <p className="text-xs text-muted-foreground/80 leading-normal mb-3">
        "Absolute jaw-dropping design! The dark glassmorphism styling and Framer Motion spring integrations compile flawlessly."
      </p>

      <div className="text-[10px] text-muted-foreground">
        <span>Author: <span className="font-bold text-foreground">Jane Doe</span></span>
        <span className="float-right">Reviewed 1d ago</span>
      </div>
    </div>
  );
}
